      funcLuaMenuCommand(711242136, BetterQoL.passive_config_plate.ITEM, k, e ~= nil)
    end
  end

  function BetterQoL.passive_config_plate.preview(slot, e)
    if type(UpdatePassiveSkillLayerInfo) ~= "function" then
      return
    end
    if e == nil then
      pcall(UpdatePassiveLayer, BetterQoL.passive_config_plate.ROWS, slot)
    elseif e.clear then
      pcall(UpdatePassiveSkillLayerInfo, BetterQoL.passive_config_plate.ROWS, slot, BetterQoL.passive_config_plate.h, slot, nil, nil, true, true)
    else
      pcall(UpdatePassiveSkillLayerInfo, BetterQoL.passive_config_plate.ROWS, 0, e.hdl, slot, nil, nil, true, false)
    end
  end

  function BetterQoL.passive_config_plate.list_guide()
    BetterQoL.passive_config_plate.guide({{BetterQoL.passive_config_plate.TX_ELEGIR, BetterQoL.passive_config_plate.GL_ENTER, BetterQoL.passive_config_plate.K_ENTER},
      {BetterQoL.passive_config_plate.TX_BACK, BetterQoL.passive_config_plate.GL_BACK, BetterQoL.passive_config_plate.K_BACK}})
  end

  -- Pointer helper (VRFW.pointer.new).
  VRFW.pointer = VRFW.pointer or {}
  VRFW.pointer.new = VRFW.pointer.new or function()
    local P = {zones = {}, on = false, x = nil, y = nil, hot = nil, prev = {}, edge_t = 0, REPEAT = 10}
    local MOVED, POS, GPOS, CHECK, CTRL = 3272825600, 558229292, 4002164178, 4265778440, 1332654303
    local LEFT, CLICK = 749879980 --[[CMD_VRFW_MOUSE_LEFT]], 1651523701 --[[CMD_ENTER_CLICK]]
    local W_UP, W_DOWN = 2649361876 --[[CMD_VRFW_WHEEL_UP]], 1098743808 --[[CMD_VRFW_WHEEL_DOWN]]
    local NAV = {1197218715, 3259546669, 2765147006, 2075023265} -- CMD_UP / DOWN / LEFT / RIGHT
    local CTRLS = {CTRL, 2748927068 --[[analog-move control: the stick's menu moves]]}
    local function M(cmd, ...)
      local ok, a, b = pcall(funcLuaMenuCommand, cmd, ...)
      if ok then return a, b end
      return nil
    end
    local function In(cmd, ctrl)
      local ok, r = pcall(funcLuaCommand, CHECK, ctrl or CTRL, cmd)
      return ok and r == true
    end
    local function Edge(cmd, ctrl)
      local key = ctrl and (tostring(ctrl) .. ":" .. tostring(cmd)) or cmd
      local now = In(cmd, ctrl)
      local was = P.prev[key]
      P.prev[key] = now
      return now and not was
    end
    --- Starts a new list of pointer zones for this frame.
    function P.begin()
      P.zones = {}
    end
    --- Adds a zone by top-left corner and size; `id` is what P.at answers, `edge` as in P.poll.
    function P.rect(x, y, w, h, id, edge)
      P.zones[#P.zones + 1] = {x, y, x + w, y + h, id = id, edge = edge}
    end
    --- Adds a zone by centre and half sizes; `id` and `edge` as in P.rect.
    function P.box(cx, cy, hw, hh, id, edge)
      P.zones[#P.zones + 1] = {cx - hw, cy - hh, cx + hw, cy + hh, id = id, edge = edge}
    end
    --- Adds a zone that follows instance idx of a layer, with half sizes hw and hh.
    function P.inst(layer, idx, hw, hh, id, edge)
      P.zones[#P.zones + 1] = {layer = layer, idx = idx, hw = hw, hh = hh, id = id, edge = edge}
    end
    --- The pointer position: x, y, or nil when it is not available.
    function P.position()
      local x, y = M(POS)
      if type(x) == "number" and type(y) == "number" then return x, y end
      return nil
    end
    --- The topmost zone under (x, y), or under the last pointer position; nil when there is none.
    function P.at(x, y)
      if x == nil then x, y = P.x, P.y end
      if x == nil then return nil end
      for i = #P.zones, 1, -1 do
        local z = P.zones[i]
        if z.layer ~= nil then
          local gx, gy = M(GPOS, z.layer, z.idx)
          if type(gx) == "number" and type(gy) == "number" and math.abs(x - gx) <= z.hw and math.abs(-y - gy) <= z.hh then
            return z
          end
        elseif x >= z[1] and x < z[3] and y >= z[2] and y < z[4] then
          return z
        end
      end
      return nil
    end
    -- (Enter / A with the pointer resting on empty space is a key Accept on the current selection)
    --- True when this press belongs to the pointer: a left click, or a click over a zone while the pointer is on.
    function P.owns()
      return In(LEFT) or (P.on and In(CLICK) and P.at() ~= nil)
    end
    --- Clears the hovered zone.
    function P.forget()
      P.hot = nil
    end
    --- Hands the cursor to the keys for this frame: pointer off, hover cleared, position remembered.
    function P.key_step()
      P.on, P.hot = false, nil
      local x, y = P.position()
      if x ~= nil then P.x, P.y = x, y end
    end
    --- Clears the zones, the hover and the edge state, and remembers the pointer position.
    function P.reset()
      P.zones, P.on, P.hot, P.prev, P.edge_t = {}, false, nil, {}, 0
      P.x, P.y = P.position()
      for _, c in ipairs({LEFT, CLICK, W_UP, W_DOWN}) do Edge(c) end
      for _, ctrl in ipairs(CTRLS) do
        for _, c in ipairs(NAV) do Edge(c, ctrl) end
      end
    end
    --- One frame of pointer input; answers this frame's event table.
    function P.poll()
      local ev = {}
      local x, y = P.position()
      if x ~= nil then
        local moved = M(MOVED) == true
        if not moved and P.x ~= nil and (math.abs(x - P.x) > 1 or math.abs(y - P.y) > 1) then
          moved = true
        end
        P.x, P.y = x, y
        if moved then
          P.on, ev.moved = true, true
        end
      end
      for _, ctrl in ipairs(CTRLS) do
        for _, c in ipairs(NAV) do
          if Edge(c, ctrl) then
            ev.keys = true
          end
        end
      end
      if ev.keys and not ev.moved then
        P.on = false
      end
      local left, click = Edge(LEFT), Edge(CLICK)
      if left then
        P.on = true
      end
      local z = P.on and P.at() or nil
      local id = z and z.id or nil
      ev.changed = id ~= P.hot
      P.hot, ev.hot = id, id
      if z ~= nil and (ev.moved or left) then
        ev.hover = id
      end
      if left then
        if z ~= nil then
          ev.click = id
        else
          ev.miss = true                 -- a mouse click on empty space: nothing
        end
      elseif click and P.on then
        if z ~= nil then
          ev.click = id
        else
          P.on, P.hot = false, nil
        end
      end
      if In(W_DOWN) then
        ev.wheel = 1
      elseif In(W_UP) then
        ev.wheel = -1
      end
      if z ~= nil and z.edge ~= nil then
        P.edge_t = P.edge_t - 1
        if P.edge_t <= 0 then
          ev.edge, P.edge_t = z.edge, P.REPEAT
        end
      else
        P.edge_t = 0
      end
      return ev
    end
    return P
  end
  BetterQoL.passive_config_plate.LAYER_GLOBAL_POS = 4002164178
  BetterQoL.passive_config_plate.PLATE_ROW_HALF_W, BetterQoL.passive_config_plate.PLATE_ROW_HALF_H = 414, 46
  BetterQoL.passive_config_plate.LIST_ROW_X, BetterQoL.passive_config_plate.LIST_ROW_W, BetterQoL.passive_config_plate.LIST_ROW_H = -98, 970, 104
  BetterQoL.passive_config_plate.CAT_LEFT, BetterQoL.passive_config_plate.CAT_RIGHT, BetterQoL.passive_config_plate.CAT_TOP, BetterQoL.passive_config_plate.CAT_H = {120, 95}, {563, 90}, -172, 56
  BetterQoL.passive_config_plate.SCROLL_BAND_H = 40
  BetterQoL.passive_config_plate.FOCUS_LOG_MAX = 200

  function BetterQoL.passive_config_plate.global_pos(L, k)
    local ok, x, y = pcall(funcLuaMenuCommand, BetterQoL.passive_config_plate.LAYER_GLOBAL_POS, L, k)
    if ok and type(x) == "number" and type(y) == "number" then
      return x, y
    end
    return nil
  end

  function BetterQoL.passive_config_plate.log_focus(where, row, by)
    BetterQoL.passive_config_plate.focus_logs = (BetterQoL.passive_config_plate.focus_logs or 0) + 1
    if BetterQoL.passive_config_plate.focus_logs <= BetterQoL.passive_config_plate.FOCUS_LOG_MAX then
      BetterQoL.passive_config_plate.log("focus", where, "row", row, "by", by)
    end
  end

  function BetterQoL.passive_config_plate.plate_row_shown(i)
    local L = BetterQoL.passive_config_plate.ROWS
    return funcLuaMenuCommand(262659071, L) == true and funcLuaMenuCommand(2640875187, L, i) == true
      and funcLuaMenuCommand(1262717583 --[[CMND_IS_LAYER_VISIBLE]], L, i) == true
  end

  -- Declares the session's zones.
  function BetterQoL.passive_config_plate.plate_row_zones(P)
    P.begin()
    for i = 0, 4 do
      if BetterQoL.passive_config_plate.plate_row_shown(i) then
        P.inst(BetterQoL.passive_config_plate.ROWS, i, BetterQoL.passive_config_plate.PLATE_ROW_HALF_W, BetterQoL.passive_config_plate.PLATE_ROW_HALF_H, i)
        if not BetterQoL.passive_config_plate.zones_logged then
          local x, y = BetterQoL.passive_config_plate.global_pos(BetterQoL.passive_config_plate.ROWS, i)
          BetterQoL.passive_config_plate.log("pointer zone plate row", i, "centre", tostring(x), tostring(y and -y))
        end
      end
    end
    BetterQoL.passive_config_plate.zones_logged = true
  end

  -- Declares the picker's zones.
  function BetterQoL.passive_config_plate.list_zones(P, list, first)
    P.begin()
    local fx, fy = BetterQoL.passive_config_plate.global_pos(BetterQoL.passive_config_plate.FILTER, 0)
    if fx ~= nil then
      P.rect(fx + BetterQoL.passive_config_plate.CAT_LEFT[1], -(fy + BetterQoL.passive_config_plate.CAT_TOP), BetterQoL.passive_config_plate.CAT_LEFT[2], BetterQoL.passive_config_plate.CAT_H, "cat_left")
      P.rect(fx + BetterQoL.passive_config_plate.CAT_RIGHT[1], -(fy + BetterQoL.passive_config_plate.CAT_TOP), BetterQoL.passive_config_plate.CAT_RIGHT[2], BetterQoL.passive_config_plate.CAT_H, "cat_right")
    end
    local top, bottom = nil, nil
    for k = 0, BetterQoL.passive_config_plate.VIEW - 1 do
      if list[first + k + 1] ~= nil then
        local x, y = BetterQoL.passive_config_plate.global_pos(BetterQoL.passive_config_plate.ITEM, k)
        if x ~= nil then
          local sy = -y - BetterQoL.passive_config_plate.LIST_ROW_H / 2
          P.rect(x + BetterQoL.passive_config_plate.LIST_ROW_X, sy, BetterQoL.passive_config_plate.LIST_ROW_W, BetterQoL.passive_config_plate.LIST_ROW_H, k)
          top = top or {x + BetterQoL.passive_config_plate.LIST_ROW_X, sy}
          bottom = {x + BetterQoL.passive_config_plate.LIST_ROW_X, sy + BetterQoL.passive_config_plate.LIST_ROW_H}
        end
      end
    end
    if top ~= nil and first > 0 then
      P.rect(top[1], top[2] - BetterQoL.passive_config_plate.SCROLL_BAND_H, BetterQoL.passive_config_plate.LIST_ROW_W, BetterQoL.passive_config_plate.SCROLL_BAND_H, "scroll_up", -1)
    end
    if bottom ~= nil and first + BetterQoL.passive_config_plate.VIEW < #list then
      P.rect(bottom[1], bottom[2], BetterQoL.passive_config_plate.LIST_ROW_W, BetterQoL.passive_config_plate.SCROLL_BAND_H, "scroll_down", 1)
    end
  end

  function BetterQoL.passive_config_plate.session_pointer()
    if BetterQoL.passive_config_plate.pointer == nil and type(VRFW.pointer.new) == "function" then
      local ok, P = pcall(VRFW.pointer.new)
      if ok then
        BetterQoL.passive_config_plate.pointer = P
      end
    end
    return BetterQoL.passive_config_plate.pointer
  end

  function BetterQoL.passive_config_plate.pointer_reset()
    local P = BetterQoL.passive_config_plate.session_pointer()
    if P ~= nil then
      pcall(P.reset)
    end
  end

  function BetterQoL.passive_config_plate.pointer_poll(zones, ...)
    local P = BetterQoL.passive_config_plate.session_pointer()
    if P == nil or not pcall(zones, P, ...) then
      return {}, false
    end
    local ok, ev = pcall(P.poll)
    if not ok or type(ev) ~= "table" then
      return {}, false
    end
    local okO, owns = pcall(P.owns)
    return ev, okO and owns == true
  end

  -- Handles the result of a set request.
  function BetterQoL.passive_config_plate.set_result(slot, ok, code)
    if ok then
      BetterQoL.passive_config_plate.SE(BetterQoL.passive_config_plate.SE_OK)
      BetterQoL.passive_config_plate.header()
      return
    end
    BetterQoL.passive_config_plate.SE(BetterQoL.passive_config_plate.SE_NG)
    BetterQoL.passive_config_plate.preview(slot, nil)
    if code == 2 then
      BetterQoL.passive_config_plate.message(BetterQoL.passive_config_plate.TX_LOCKED)
    elseif code == 7 then
      BetterQoL.passive_config_plate.message(BetterQoL.passive_config_plate.TX_LIMIT)
    elseif code == 4 then
      BetterQoL.passive_config_plate.message(BetterQoL.passive_config_plate.TX_DUP)
    else
      BetterQoL.passive_config_plate.message(BetterQoL.passive_config_plate.TX_FAIL)
    end
  end

  function BetterQoL.passive_config_plate.pick(slot)
    BetterQoL.passive_config_plate.VIEW = BetterQoL.passive_config_plate.rows()
    local cat = 0
    local list, init
    list, cat, init = BetterQoL.passive_config_plate.build(slot, cat)
    if #list == 0 and BetterQoL.passive_config_plate.kind(slot) == 1 then
      -- Handles a special slot (declared slot rules) with no special for this player.
      local none = BetterQoL.passive_config_plate.text(BetterQoL.passive_config_plate.TX_SPECIAL_NONE)
      list = {{idx = -1, none = true, text = none, icon = 0, build = -1, special = true}}
      init = 0
    end
    if #list == 0 then
      BetterQoL.passive_config_plate.SE(BetterQoL.passive_config_plate.SE_NG)
      return
    end
    local sel = init
    local first = math.max(0, math.min(sel, #list - BetterQoL.passive_config_plate.VIEW))
    BetterQoL.passive_config_plate.mark(-1)
    BetterQoL.passive_config_plate.list_show(true, list, first, sel)
    BetterQoL.passive_config_plate.filter(true, cat)
    BetterQoL.passive_config_plate.preview(slot, list[sel + 1])
    BetterQoL.passive_config_plate.list_guide()
    coroutine.yield()
    local chosen = nil
    BetterQoL.passive_config_plate.pointer_reset()
    while true do
      coroutine.yield()
      local moved = false
      local by = "pad"
      local cat_dir = nil
      local ev, owns = BetterQoL.passive_config_plate.pointer_poll(BetterQoL.passive_config_plate.list_zones, list, first)
      local clicked = ev.click
      local scroll = ev.wheel or ev.edge
      if BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_BACK) then
        BetterQoL.passive_config_plate.SE(BetterQoL.passive_config_plate.SE_BACK)
        break
      elseif type(clicked) == "number" or (not owns and (BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_ENTER) or BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_CLICK))) then
        if type(clicked) == "number" and list[first + clicked + 1] ~= nil then
          sel = first + clicked
          BetterQoL.passive_config_plate.log_focus("list", sel, "mouse click")
        end
        chosen = list[sel + 1]
        break
      elseif clicked == "cat_left" or clicked == "cat_right" then
        cat_dir = clicked == "cat_left" and -1 or 1
        by = "mouse"
      elseif type(ev.hover) == "number" and list[first + ev.hover + 1] ~= nil and first + ev.hover ~= sel then
        sel = first + ev.hover
        moved = true
        by = "mouse"
      elseif scroll ~= nil then
        -- Handles the wheel and scroll band.
        local first2 = math.max(0, math.min(first + scroll, #list - BetterQoL.passive_config_plate.VIEW))
        if first2 ~= first then
          first = first2
          if type(ev.hot) == "number" and list[first + ev.hot + 1] ~= nil then
            sel = first + ev.hot
          else
            sel = math.max(first, math.min(sel, first + BetterQoL.passive_config_plate.VIEW - 1))
          end
          moved = true
          by = "mouse"
        end
      elseif BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_DOWN) and sel < #list - 1 then
        sel = sel + 1
        if sel >= first + BetterQoL.passive_config_plate.VIEW then
          first = first + 1
        end
        moved = true
      elseif BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_UP) and sel > 0 then
        sel = sel - 1
        if sel < first then
          first = first - 1
        end
        moved = true
      elseif BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_L1) or BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_R1) then
        cat_dir = BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_L1) and -1 or 1
      end
      if cat_dir ~= nil then
        local dir = cat_dir
        local ok, c = pcall(funcLuaCommand, BetterQoL.passive_config_plate.CMD_CAT_NEXT, BetterQoL.passive_config_plate.h, slot, cat, dir)
        if ok and type(c) == "number" and c ~= cat then
          local l2, c2 = BetterQoL.passive_config_plate.build(slot, c)
          if #l2 > 0 then
            list, cat = l2, c2
            sel = 0
            for k, e in ipairs(list) do
              if e.current then
                sel = k - 1
              end
            end
            first = math.max(0, math.min(sel, #list - BetterQoL.passive_config_plate.VIEW))
            BetterQoL.passive_config_plate.filter(true, cat)
            moved = true
          end
        end
      end
      if moved then
        BetterQoL.passive_config_plate.SE(BetterQoL.passive_config_plate.SE_MOVE)
        BetterQoL.passive_config_plate.list_show(true, list, first, sel)
        BetterQoL.passive_config_plate.preview(slot, list[sel + 1])
        BetterQoL.passive_config_plate.log_focus("list", sel, by)
      end
    end
    BetterQoL.passive_config_plate.list_show(false, list, first, sel)
    if chosen ~= nil and not chosen.none then
      local id = 0
      if not chosen.clear then
        id = funcLuaCommand(BetterQoL.passive_config_plate.CMD_LIST_ID, chosen.idx)
      end
      local ok, code = funcLuaCommand(BetterQoL.passive_config_plate.CMD_SET, BetterQoL.passive_config_plate.h, slot, id)
      BetterQoL.passive_config_plate.log("set", BetterQoL.passive_config_plate.h, slot, id, ok, code)
      BetterQoL.passive_config_plate.set_result(slot, ok, code)
    else
      BetterQoL.passive_config_plate.preview(slot, nil)
    end
    coroutine.yield()
  end

  -- Returns the next sub page row.
  function BetterQoL.passive_config_plate.next_sub_page_row()
    local page = type(CharacterReforged) == "table" and CharacterReforged.player_page or nil
    if type(page) ~= "table" or type(page.next_passive_sub_page) ~= "function" or type(page.psub) ~= "number" then
      return nil
    end
    local rows = page.PSUB[page.next_passive_sub_page()]
    for _, row in ipairs(rows) do
      if not BetterQoL.passive_config_plate.locked(row) then
        return row
      end
    end
    return rows[1]
  end

  -- Starts the session.
  function BetterQoL.passive_config_plate.session(h)
    local ok, got, mode, _, _, max_slots, inactive = pcall(funcLuaCommand, BetterQoL.passive_config_plate.CMD_INFO, h)
    if not ok or got ~= true or type(mode) ~= "number" or mode <= 0 then
      return
    end
    BetterQoL.passive_config_plate.h, BetterQoL.passive_config_plate.mode = h, mode
    BetterQoL.passive_config_plate.max_slots = type(max_slots) == "number" and max_slots or 5
    BetterQoL.passive_config_plate.log("session", h, "mode", mode, "max_slots", BetterQoL.passive_config_plate.max_slots, "inactive", inactive)
    if type(UpdatePersonalPlatePage) == "function" then
      pcall(UpdatePersonalPlatePage, 2)
    end
    coroutine.yield()
    BetterQoL.passive_config_plate.draw_rows()
    if type(inactive) == "number" and inactive > 0 then
      -- Handles stored choices that the current rules do not apply (more than max_slots, or of the wrong kind).
      BetterQoL.passive_config_plate.message(BetterQoL.passive_config_plate.TX_INACTIVE)
    end
    local sel = 0
    while sel < 4 and BetterQoL.passive_config_plate.locked(sel) do
      sel = sel + 1
    end
    BetterQoL.passive_config_plate.slot = sel
    BetterQoL.passive_config_plate.mark(sel)
    BetterQoL.passive_config_plate.rows_guide(sel)
    coroutine.yield()
    BetterQoL.passive_config_plate.zones_logged = false
    BetterQoL.passive_config_plate.pointer_reset()
    -- focus on row `to` (d-pad or pointer)
    local function FocusRow(to, by)
      sel = to
      BetterQoL.passive_config_plate.slot = sel
      BetterQoL.passive_config_plate.SE(BetterQoL.passive_config_plate.SE_MOVE)
      BetterQoL.passive_config_plate.mark(sel)
      BetterQoL.passive_config_plate.rows_guide(sel)
      BetterQoL.passive_config_plate.log_focus("plate", sel, by)
    end
    while true do
      coroutine.yield()
      local ev, owns = BetterQoL.passive_config_plate.pointer_poll(BetterQoL.passive_config_plate.plate_row_zones)
      local clicked = type(ev.click) == "number" and ev.click or nil
      if BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_BACK) then
        BetterQoL.passive_config_plate.SE(BetterQoL.passive_config_plate.SE_BACK)
        break
      elseif clicked ~= nil or (not owns and (BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_ENTER) or BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_CLICK))) then
        if clicked ~= nil and clicked ~= sel then
          sel = clicked
          BetterQoL.passive_config_plate.slot = sel
          BetterQoL.passive_config_plate.mark(sel)
          BetterQoL.passive_config_plate.log_focus("plate", sel, "mouse click")
        end
        if BetterQoL.passive_config_plate.locked(sel) then
          BetterQoL.passive_config_plate.SE(BetterQoL.passive_config_plate.SE_NG)
          BetterQoL.passive_config_plate.message(BetterQoL.passive_config_plate.lock_text(sel))
        else
          BetterQoL.passive_config_plate.SE(BetterQoL.passive_config_plate.SE_OK)
          BetterQoL.passive_config_plate.pick(sel)
          BetterQoL.passive_config_plate.draw_rows()
          BetterQoL.passive_config_plate.mark(sel)
        end
        BetterQoL.passive_config_plate.rows_guide(sel)
        BetterQoL.passive_config_plate.pointer_reset()
      elseif type(ev.hover) == "number" and ev.hover ~= sel then
        FocusRow(ev.hover, "mouse")
      elseif BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_DOWN) and sel < 4 then
        FocusRow(sel + 1, "pad")
      elseif BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_UP) and sel > 0 then
        FocusRow(sel - 1, "pad")
      elseif BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_R3) then
        local to = BetterQoL.passive_config_plate.next_sub_page_row()
        if to ~= nil then
          FocusRow(to, "sub-page key")
        end
      elseif BetterQoL.passive_config_plate.key(BetterQoL.passive_config_plate.K_FUNC3) then
        local okS, _, configured, locked, stored = pcall(funcLuaCommand, BetterQoL.passive_config_plate.CMD_SLOT, h, sel)
        -- Handles a configured row or an inactive stored choice.
        if okS and not locked and (configured or (type(stored) == "number" and stored ~= 0)) then
          local okC, code = funcLuaCommand(BetterQoL.passive_config_plate.CMD_SET, h, sel, 0)
          BetterQoL.passive_config_plate.set_result(sel, okC, code)
          BetterQoL.passive_config_plate.draw_rows()
          BetterQoL.passive_config_plate.mark(sel)
          BetterQoL.passive_config_plate.rows_guide(sel)
          BetterQoL.passive_config_plate.pointer_reset()
        else
          BetterQoL.passive_config_plate.SE(BetterQoL.passive_config_plate.SE_NG)
        end
      end
    end
    BetterQoL.passive_config_plate.slot = nil
    BetterQoL.passive_config_plate.mark(-1)
    BetterQoL.passive_config_plate.mode = 0
    BetterQoL.passive_config_plate.draw_rows()
  end

  function BetterQoL.passive_config_plate.finish()
    BetterQoL.passive_config_plate.co = nil
    BetterQoL.passive_config_plate.pointer = nil
    BetterQoL.passive_config_plate.slot = nil
    pcall(BetterQoL.passive_config_plate.mark, -1)
    pcall(BetterQoL.passive_config_plate.list_show, false, {}, 0, 0)
    BetterQoL.passive_config_plate.log("session end")
    VRFW.param.clear(BetterQoL.passive_config_plate.KEY_DONE)
    VRFW.param.set(BetterQoL.passive_config_plate.KEY_DONE, 1)
  end

  -- Resumes the session coroutine.
  function BetterQoL.passive_config_plate.resume(...)
    local ok, err = coroutine.resume(BetterQoL.passive_config_plate.co, ...)
    if not ok then
      BetterQoL.passive_config_plate.log("session error", err)
      BetterQoL.passive_config_plate.finish()
    elseif coroutine.status(BetterQoL.passive_config_plate.co) == "dead" then
      BetterQoL.passive_config_plate.finish()
    end
  end

  -- Polls every frame.
  function BetterQoL.passive_config_plate.poll()
    BetterQoL.passive_config_plate.hook_header()
    if BetterQoL.passive_config_plate.co ~= nil then
      BetterQoL.passive_config_plate.resume()
      return
    end
    if not VRFW.param.has(BetterQoL.passive_config_plate.KEY_REQ) then
      return
    end
    local h = VRFW.param.get(BetterQoL.passive_config_plate.KEY_REQ)
    VRFW.param.clear(BetterQoL.passive_config_plate.KEY_REQ)
    BetterQoL.passive_config_plate.parent = 0
    if VRFW.param.has(BetterQoL.passive_config_plate.KEY_PARENT) then
      BetterQoL.passive_config_plate.parent = VRFW.param.get(BetterQoL.passive_config_plate.KEY_PARENT)
      VRFW.param.clear(BetterQoL.passive_config_plate.KEY_PARENT)
    end
    BetterQoL.passive_config_plate.co = coroutine.create(BetterQoL.passive_config_plate.session)
    BetterQoL.passive_config_plate.resume(h)
  end

  BetterQoL.passive_config_plate.wrap("PostStep", function(prev)
    return function(...)
      local r
      if prev then
        r = prev(...)
      end
      pcall(BetterQoL.passive_config_plate.poll)
      if BetterQoL.passive_config_plate.off and BetterQoL.passive_config_plate.co == nil then
        pcall(BetterQoL.passive_config_plate.hide_rows)
      end
      pcall(BetterQoL.passive_config_plate.decorate)
      return r
    end
  end, true)

  -- Shared passive-icon kit (included as @ICONS@)
  BetterQoL = BetterQoL or {}
  BetterQoL.passive_icons = BetterQoL.passive_icons or {}
  BetterQoL.passive_icons.CMD_INFO = 3569354349
  BetterQoL.passive_icons.ICON_TEX = 2320109963 -- #/menu/200_icon/15_icon_common/icon_common.g4tx
  BetterQoL.passive_icons.LOCK_MESH = 1670039012
  BetterQoL.passive_icons.LOCK_DUMMY = 3276571178
  BetterQoL.passive_icons.LAYERS = BetterQoL.passive_icons.LAYERS or {}
  BetterQoL.passive_icons.LAYERS[1844915256] = true -- soccer11_04_formation_chara_status (plate, team dock)
  BetterQoL.passive_icons.LAYERS[607716004] = true -- soccer11_04_chara_status (skill screen)

  -- Constants for the list picker rows (better_qol_pc_row).
  BetterQoL.passive_icons.PLATE_TEX = 4021797290 -- #/menu/00_soccer/soccer11/soccer11_20/soccer11_20.g4tx
  BetterQoL.passive_icons.ROW_BACK_MESH = 2172872396
  BetterQoL.passive_icons.ROW_BACK_DUMMY = 1011017977 -- icon_cmd_type_base01
  BetterQoL.passive_icons.ROW_MASKED_MESH = 1255155594
  BetterQoL.passive_icons.PLATE_SLOT = 2597149412 -- teambuff_base01
  -- Special passive tile (soccer11_20 sprite) set by a plate session.
  BetterQoL.passive_icons.SPECIAL_TILE = BetterQoL.passive_icons.SPECIAL_TILE or 0

  -- mods' effect icons (sprite of the per-language atlas icon_teambuff), asked once per effect and VM
  BetterQoL.passive_icons.TEAMBUFF_TEX = 2301895383 -- #/menu/200_icon/08_icon_teambuff/<LG>/icon_teambuff.g4tx
  BetterQoL.passive_icons.TEAMBUFF_SLOT = 3234721532 -- icon_teambuff_dmy01 (the retail row's buff icon slot)
  BetterQoL.passive_icons.CMD_EFF_ICON = 3492059690
  BetterQoL.passive_icons.EFF_ICON = BetterQoL.passive_icons.EFF_ICON or {}
  function BetterQoL.passive_icons.eff_icon(eff)
    if type(eff) ~= "number" or eff == 0 then
      return nil
    end
    local v = BetterQoL.passive_icons.EFF_ICON[eff]
    if v == nil then
      local spr = VRFW.host.command(BetterQoL.passive_icons.CMD_EFF_ICON, eff)
      v = (type(spr) == "number") and spr or 0
      BetterQoL.passive_icons.EFF_ICON[eff] = v
    end
    return v ~= 0 and v or nil
  end
  function BetterQoL.passive_icons.row_eff_icon(L, k, eff)
    local spr = BetterQoL.passive_icons.eff_icon(eff)
    if spr ~= nil then
      VRFW.host.menu_command(558735651, L, BetterQoL.passive_icons.TEAMBUFF_TEX, spr, BetterQoL.passive_icons.TEAMBUFF_SLOT, 0, k)
    end
    return spr ~= nil
  end
  function BetterQoL.passive_icons.row_backing(L, k, show, badge, special)
    funcLuaMenuCommand(3405944500, L, BetterQoL.passive_icons.ROW_MASKED_MESH, false, k)
    funcLuaMenuCommand(3405944500, L, BetterQoL.passive_icons.ROW_BACK_MESH, show == true, k)
    if show then
      local tile = special and BetterQoL.passive_icons.SPECIAL_TILE ~= nil and BetterQoL.passive_icons.SPECIAL_TILE ~= 0 and BetterQoL.passive_icons.SPECIAL_TILE or nil
      VRFW.host.menu_command(558735651, L, BetterQoL.passive_icons.PLATE_TEX, tile or (badge and 63179614) or BetterQoL.passive_icons.PLATE_SLOT,
        BetterQoL.passive_icons.ROW_BACK_DUMMY, 0, k)
    end
  end

  function BetterQoL.passive_icons.dual_icon(L, idx, h, kind)
    if not BetterQoL.passive_icons.LAYERS[L] or type(h) ~= "number" or h == 0 or kind == 6 then
      return
    end
    idx = idx or 0
    if type(GetBuildTypeIconTextureNameByCharaStHdl) == "function" and GetBuildTypeIconTextureNameByCharaStHdl(h) == 0 then
      return
    end
    local got, _, a, b = VRFW.host.command(BetterQoL.passive_icons.CMD_INFO, h)
    if got ~= true or type(a) ~= "number" or type(b) ~= "number" then
      return
    end
    if a < 0 or a > 5 or b < 0 or b > 5 or a == b or type(GeTeamBuffBuildTypeIconTextureName) ~= "function" then
      return
    end
    local tex = GeTeamBuffBuildTypeIconTextureName(b)
    if tex == nil or tex == 0 then
      return
    end
    funcLuaMenuCommand(558735651, L, BetterQoL.passive_icons.ICON_TEX, tex, BetterQoL.passive_icons.LOCK_DUMMY, 0, idx)
    funcLuaMenuCommand(3405944500, L, BetterQoL.passive_icons.LOCK_MESH, true, idx)
  end

  -- Installs the wrapper around the named function.
  BetterQoL.passive_icons.done = BetterQoL.passive_icons.done or {}
  function BetterQoL.passive_icons.direct_wrap(name, make)
    local cur = _ENV[name]
    if type(cur) ~= "function" or BetterQoL.passive_icons.done[name] then
      return BetterQoL.passive_icons.done[name] == true
    end
    _ENV[name] = make(cur)
    BetterQoL.passive_icons.done[name] = true
    return true
  end
  function BetterQoL.passive_icons.install(wrap)
    wrap = wrap or BetterQoL.passive_icons.direct_wrap
    if BetterQoL.passive_icons.installed == wrap then
      return
    end
    local a = wrap("SwapPassiveSkillEffectIcon", function(prev)
      return function(L, k, eff, ...)
        local r = table.pack(prev(L, k, eff, ...))
        pcall(BetterQoL.passive_icons.row_eff_icon, L, k, eff)
        return table.unpack(r, 1, r.n)
      end
    end)
    local b = wrap("UpdateCharaStatusPlateInfoByCharaStHdl", function(prev)
      return function(a1, a2, a3, a4, a5, a6, ...)
        local r1, r2, r3, r4 = prev(a1, a2, a3, a4, a5, a6, ...)
        pcall(BetterQoL.passive_icons.dual_icon, a1, a2, a3, a6)
        return r1, r2, r3, r4
      end
    end)
    if a and b then
      BetterQoL.passive_icons.installed = wrap
    end
  end
  function BetterQoL.passive_icons.hook()
    if BetterQoL.passive_icons.installed == nil then
      BetterQoL.passive_icons.install(BetterQoL.passive_icons.direct_wrap)
    end
  end
  BetterQoL.passive_icons.install(BetterQoL.passive_config_plate.wrap)

  -- redraw the header after a change, as the plate's own OnOpenLayer does
  function BetterQoL.passive_config_plate.header()
    if type(UpdateCharaStatusPlateInfo) ~= "function" then
      return
    end
    local h = nil
    if type(GetPersonalPlateSelectCharaStHdl) == "function" then
      local ok, v = pcall(GetPersonalPlateSelectCharaStHdl)
      if ok and type(v) == "number" and v ~= 0 then
        h = v
      end
    end
    h = h or BetterQoL.passive_config_plate.h
    if h ~= nil then
      pcall(UpdateCharaStatusPlateInfo, h)
    end
  end

  function BetterQoL.passive_config_plate.hook_header()
    BetterQoL.passive_icons.install(BetterQoL.passive_config_plate.wrap)
  end

  function BetterQoL.passive_config_plate.own_layer(a1)
    return a1 == BetterQoL.passive_config_plate.BG or a1 == BetterQoL.passive_config_plate.LIST or a1 == BetterQoL.passive_config_plate.ITEM or a1 == BetterQoL.passive_config_plate.FILTER
  end

  -- the picker layers start hidden, above the team dock
  BetterQoL.passive_config_plate.wrap("OnSetupLayer", function(prev)
    return function(a1, a2, ...)
      if BetterQoL.passive_config_plate.own_layer(a1) then
        local prio = (a1 == BetterQoL.passive_config_plate.BG and 449) or (a1 == BetterQoL.passive_config_plate.LIST and 450) or (a1 == BetterQoL.passive_config_plate.FILTER and 452) or 451
        funcLuaMenuCommand(1491630496, a1, a2, prio, true)
        if a1 == BetterQoL.passive_config_plate.LIST then
          funcLuaMenuCommand(2158717427, a1, 1839509013, false, a2)
          funcLuaMenuCommand(2158717427, a1, 1060758565, false, a2)
          funcLuaMenuCommand(3405944500, a1, 3660005257, false, a2)
        end
        funcLuaMenuCommand(711242136, a1, a2, false)
        return
      end
      return prev(a1, a2, ...)
    end
  end)
  BetterQoL.passive_config_plate.wrap("OnOpenLayer", function(prev)
    return function(a1, a2, ...)
      if BetterQoL.passive_config_plate.own_layer(a1) then
        if BetterQoL.passive_config_plate.co == nil then
          funcLuaMenuCommand(711242136, a1, a2, false)
        end
        return
      end
      return prev(a1, a2, ...)
    end
  end)
end
